#!/bin/sh
#
# Add the licence notices and the written source offer to an EXISTING boot.img
# without rebuilding it: the same LICENSES/ directory and SOURCE-OFFER.txt that
# assemble-boot-img.sh writes at build time, generated by the same script from
# the same source-offer.env. For the rebake path, where only the agent inside
# the rootfs changes and the image is then re-signed.
#
# Usage: scripts/inject-notices.sh [options] <boot.img>
#
#   --legal-info DIR        Buildroot legal-info directory for the component
#                           list (default: the committed list for the base)
#   --firmware-licence FILE LICENCE.broadcom to embed (default: the committed copy)
#   --agent-notices FILE    the baked agent's THIRD-PARTY-NOTICES.md (the
#                           agent release package's copy, or
#                           agent/THIRD-PARTY-NOTICES.md at the release tag of
#                           https://github.com/uptime-lab/orchestrator-agent;
#                           default: the committed copy)
#   --env FILE              source-offer.env to read
#   --dry-run               generate the files and list what would be copied,
#                           touching neither the image nor mtools
#
# Requires: mtools (mcopy, mmd, mdir, mtype) unless --dry-run. Operate on a
# COPY of a served image and re-sign afterwards: the script refuses an image
# whose boot.sig beside it still matches, because injecting in place would
# leave the served bytes unsigned until the signature is redone.

set -eu

HERE=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
NOTICES="$HERE/../br2-orchestrator/board/orchestrator/notices/make-notices.sh"

IMG=""
DRY_RUN=0
GEN_ARGS=""
ENV_ARGS=""

usage() { sed -n '2,26p' "$0" | sed 's/^# \{0,1\}//' >&2; exit 2; }

while [ $# -gt 0 ]; do
  case "$1" in
    --legal-info|--firmware-licence|--agent-notices)
      [ $# -ge 2 ] || { echo "inject-notices: $1 needs a value" >&2; usage; }
      GEN_ARGS="$GEN_ARGS $1 $2"; shift 2 ;;
    --env)
      [ $# -ge 2 ] || { echo "inject-notices: $1 needs a value" >&2; usage; }
      GEN_ARGS="$GEN_ARGS --env $2"; ENV_ARGS="--env $2"; shift 2 ;;
    --dry-run) DRY_RUN=1; shift ;;
    -h|--help) usage ;;
    -*) echo "inject-notices: unknown option $1" >&2; usage ;;
    *) [ -z "$IMG" ] || usage; IMG=$1; shift ;;
  esac
done
[ -n "$IMG" ] || usage
[ -f "$IMG" ] || { echo "inject-notices: not a file: $IMG" >&2; exit 2; }
[ -s "$IMG" ] || { echo "inject-notices: empty image: $IMG" >&2; exit 2; }
[ -x "$NOTICES" ] || { echo "inject-notices: generator not found: $NOTICES" >&2; exit 2; }

sha256_of() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1
  elif command -v shasum >/dev/null 2>&1; then shasum -a 256 "$1" | cut -d' ' -f1
  else echo ""; fi
}

# A boot.sig beside the image whose first line is the image's sha256 means this
# is the signed, served artifact; a rebake works on a copy, which is re-signed
# before it replaces the served one.
SIG="$(dirname -- "$IMG")/boot.sig"
if [ -f "$SIG" ] && [ "$DRY_RUN" -eq 0 ]; then
  sum=$(sha256_of "$IMG")
  if [ -n "$sum" ] && [ "$(head -1 "$SIG" | tr -d '\r\n ')" = "$sum" ]; then
    echo "inject-notices: $IMG is the image $SIG signs; copy it and inject into the copy, then re-sign" >&2
    exit 2
  fi
fi

STAGE=$(mktemp -d)
trap 'rm -rf "$STAGE"' EXIT

# shellcheck disable=SC2086
"$NOTICES" --out "$STAGE" $GEN_ARGS

total=0
for f in "$STAGE/LICENSES"/* "$STAGE/SOURCE-OFFER.txt"; do
  total=$((total + $(wc -c < "$f")))
done

if [ "$DRY_RUN" -eq 1 ]; then
  echo "inject-notices: dry run; would copy into $IMG ($total bytes):"
  (cd "$STAGE" && find . -type f | sed 's|^\./|  |' | sort)
  exit 0
fi

for tool in mcopy mmd mdir mtype; do
  command -v "$tool" >/dev/null 2>&1 || { echo "inject-notices: $tool (mtools) is not installed" >&2; exit 2; }
done

# Free space, read from the image itself. A FAT image has a fixed size, and
# overwriting an existing copy of a file frees its clusters first, so the
# existing notices do not count against the new ones.
# mdir groups digits with spaces ("37 134 336 bytes free"), hence the strip.
free=$(mdir -i "$IMG" :: | grep 'bytes free' | tail -1 | sed 's/ bytes free.*//' | tr -dc '0-9')
existing=0
for f in SOURCE-OFFER.txt LICENSES/GPL-2.0.txt LICENSES/GPL-3.0.txt LICENSES/LGPL-2.1.txt \
         LICENSES/Apache-2.0.txt LICENSES/LICENCE.broadcom LICENSES/NOTICE-orchestrator-agent.txt \
         LICENSES/THIRD-PARTY-NOTICES.txt LICENSES/THIRD-PARTY-NOTICES-orchestrator-agent.md; do
  size=$(mtype -i "$IMG" "::$f" 2>/dev/null | wc -c | tr -d ' ')
  existing=$((existing + ${size:-0}))
done
if [ -n "$free" ] && [ $((free + existing)) -lt "$total" ]; then
  echo "inject-notices: $IMG has $free bytes free (+$existing in notices already there), need $total" >&2
  exit 1
fi

if ! mdir -i "$IMG" ::LICENSES >/dev/null 2>&1; then
  mmd -i "$IMG" ::LICENSES
fi
mcopy -o -i "$IMG" "$STAGE/LICENSES"/* ::LICENSES/
mcopy -o -i "$IMG" "$STAGE/SOURCE-OFFER.txt" ::

# shellcheck disable=SC2086
"$HERE/check-notices.sh" $ENV_ARGS "$IMG"
echo "inject-notices: done; re-sign $IMG before serving it"
